'use strict';
const L=LoganLogs,parseTimers=new Map();let importDraft=null,importReadId=0;
function logImportError(message){let node=$('#import-error');if(node)node.textContent=message;else toast(message);}
function openLogImport(){importDraft={files:[],ready:false,reading:false};openModal('上传导入日志 · 仅此浏览器',`<form onsubmit="submitLogImport(event)"><div class="notice">文件只在此浏览器读取、解析和保存，不会上传服务器。支持 UTF-8 明文 JSONL、JSON 数组和“时间 级别 模块 内容”文本；不解密 Logan 原始加密文件。</div><div class="form-grid"><div><label for="import-issue">关联工单</label><select id="import-issue">${state.issues.map(i=>`<option value="${i.id}" ${i.id===state.active?'selected':''}>${esc(i.id+' · '+i.title)}</option>`).join('')}</select></div><div><label for="import-platform">日志平台</label><select id="import-platform"><option>Web</option><option>Native</option></select></div><div><label for="import-device">设备 / 浏览器标识 *</label><input id="import-device" required value="${esc(issue().device)}"></div><div><label for="import-version">应用版本 *</label><input id="import-version" required value="${esc(issue().version)}"></div><div><label for="import-build">构建号 *</label><input id="import-build" required value="${esc(issue().build)}"></div></div><div class="form-grid"><div><label for="import-begin">日志开始时间</label><input id="import-begin" type="datetime-local" required value="${issue().begin}"></div><div><label for="import-end">日志结束时间</label><input id="import-end" type="datetime-local" required value="${issue().end}"></div></div><label for="import-files">选择本地日志文件 *</label><input id="import-files" type="file" multiple accept=".jsonl,.json,.log,.txt" onchange="readImportFiles(this.files)"><small>最多 5 个文件，单文件 256 KiB，每次 512 KiB；本地原文件总量上限 2 MiB，最多解析 2000 条事件。</small><div id="import-preview" class="panel"><p>选择文件后显示预览，不会执行文件内容。</p></div>${parseOptions('import','auto','strict')}<p id="import-error" class="error" role="alert"></p><div class="toolbar"><button class="primary" id="import-submit" disabled>保存文件并创建解析批次</button><button type="button" onclick="closeModal()">取消</button></div></form>`,true);}
function parseOptions(prefix,format,policy){return `<div class="form-grid"><div><label for="${prefix}-format">解析格式</label><select id="${prefix}-format">${[['auto','自动识别'],['jsonl','JSONL（每行一个对象）'],['json','JSON 数组'],['text','明文（时间 级别 模块 内容）']].map(([v,text])=>`<option value="${v}" ${v===format?'selected':''}>${text}</option>`).join('')}</select></div><div><label for="${prefix}-policy">错误行处理</label><select id="${prefix}-policy"><option value="strict" ${policy==='strict'?'selected':''}>严格：有错误则不发布索引</option><option value="skip" ${policy==='skip'?'selected':''}>隔离错误：发布其余有效记录</option></select></div></div>`;}
async function readImportFiles(files){let id=++importReadId,draft=importDraft;draft.ready=false;draft.reading=true;$('#import-submit').disabled=true;$('#import-error').textContent='';try{if(!files.length||files.length>5)throw Error('请选择 1—5 个文件');let list=[...files];if(list.some(f=>f.size>L.limits.file))throw Error('单文件超过 256 KiB 上限');if(list.reduce((n,f)=>n+f.size,0)>L.limits.total)throw Error('每次导入超过 512 KiB 上限');let data=await Promise.all(list.map(async f=>{try{return {name:f.name,text:new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(await f.arrayBuffer())};}catch{throw Error(f.name+' 不是有效的 UTF-8 明文文件');}}));if(id!==importReadId||draft!==importDraft||!$('#import-preview'))return;let problem=data.find(f=>!f.text.trim()||!(/\.(jsonl|json|log|txt)$/i.test(f.name))||f.text.includes('\u0000'));if(problem)throw Error(problem.name+' 为空、格式不支持或包含二进制内容');draft.files=data;draft.ready=true;$('#import-preview').innerHTML=data.map(f=>`<section><b>${esc(f.name)}</b><small> · ${new TextEncoder().encode(f.text).length} B</small><pre class="file-preview">${esc(f.text.slice(0,600))}</pre></section>`).join('');$('#import-submit').disabled=false;}catch(e){if(id===importReadId)logImportError(e.message);}finally{draft.reading=false;}}
function submitLogImport(e){e.preventDefault();let backup=JSON.stringify(state);if(!importDraft?.ready||importDraft.reading)return logImportError('请先选择并完成文件读取');try{let i=state.issues.find(x=>x.id===$('#import-issue').value),result=L.importFiles(state,i,{platform:$('#import-platform').value,device:$('#import-device').value,version:$('#import-version').value,build:$('#import-build').value,begin:$('#import-begin').value,end:$('#import-end').value,files:importDraft.files,format:$('#import-format').value,policy:$('#import-policy').value});if(!save()){state=JSON.parse(backup);throw Error('浏览器本地存储不足，未保存导入；原有记录已保留。');}state.active=i.id;let r=result.asset.runs.at(-1);selectAssetRun(result.asset,r);closeModal();toast(result.duplicate?'相同文件与元数据已导入，打开已有批次':'原文件已保存；请开始本地解析');}catch(err){logImportError(err.message);}}
function selectAssetRun(a,r){syncImportedIssueState();state.active=a.issueId;taskId=r.task;requestId=null;selected=0;query='';level='全部';contextMode=false;workUI.logKey=a.id+'/'+r.id;workUI.logMode='parse';workUI.logStatus='';workUI.logQuery='';save();go('logcenter');}
function findAsset(id){for(let i of state.issues){let a=(i.logAssets||[]).find(a=>a.id===id);if(a)return a;}return null;}
function loadWebLogSample(){openModal('载入 Web 日志样例',`<form onsubmit="commitWebLogSample(event)"><p>创建浏览器登录超时的合成文件：5 条 Web 事件、requestId=web-req-642，对应 TSX / TypeScript 源码样例。</p><label for="sample-issue">样例关联工单</label><select id="sample-issue">${state.issues.map(i=>`<option value="${i.id}" ${i.id===state.active?'selected':''}>${esc(i.id+' · '+i.title)}</option>`).join('')}</select><dl><dt>浏览器 / 构建</dt><dd>browser-demo-01 / web-38107</dd><dt>日志范围（北京时间）</dt><dd>2026-10-20 10:40—10:45</dd><dt>文件</dt><dd>web-login-demo.jsonl · 5 条事件</dd></dl><p id="sample-error" class="error" role="alert"></p><div class="toolbar"><button class="primary">载入样例并创建解析批次</button><button type="button" onclick="closeModal()">取消</button></div></form>`);}
function commitWebLogSample(e){e.preventDefault();let backup=JSON.stringify(state);try{let i=state.issues.find(i=>i.id===$('#sample-issue').value),a=L.webSample(state,i);if(!save()){state=JSON.parse(backup);throw Error('浏览器存储不足，未保存样例，已有记录保留。');}closeModal();selectAssetRun(a,a.runs.at(-1));toast('Web 样例文件已载入，等待解析；未发送网络请求');}catch(err){$('#sample-error').textContent=err.message;}}

function downloadWebLogSample(){let temp={issues:[],logSequence:1},i={id:'sample',logAssets:[]};temp.issues=[i];let a=L.webSample(temp,i);file('web-login-demo.jsonl',a.files[0].text);}
const originalParseView=parseView;
parseView=function(x){if(x.asset)return assetParseView(x);return originalParseView(x)+`<div class="panel"><h3>重新解析原文件</h3><p>独立重新解析不会再次推送设备。旧请求、错误记录与旧任务保留。</p><div class="notice">此历史回捞只保存了合成文件结果。重新解析使用对应种类的合成明文文件快照，不能代替真实加密原文件解码。</div>${btn('创建重新解析批次',`reparseCollection('${x.key}')`,'',!x.request.files.some(f=>['已上传','可查','解析失败'].includes(f.status)))}${state.issues.flatMap(i=>i.logAssets||[]).filter(a=>a.sourceKey===x.key).map(a=>`<p>${a.id} · ${a.runs.length} 个批次 ${btn('查看解析历史',`selectAssetRun(findAsset('${a.id}'),findAsset('${a.id}').runs.at(-1))`)}</p>`).join('')}</div>`;};
function reparseCollection(key){let x=fullLogSources().find(x=>x.key===key);let previous=(x.issue.logAssets||[]).find(a=>a.sourceKey===key);if(previous)return openReparse(previous.id);let files=x.request.files.filter(f=>['已上传','可查','解析失败'].includes(f.status)).map(f=>{let kind=f.name.replace('.log','');return {name:f.name,text:records.filter(r=>kind===(r.module==='Network'?'网络日志':'应用日志')).map(r=>r.time+' '+r.level+' '+r.module+' '+r.content).join('\n')};});try{let a=L.importFiles(state,x.issue,{platform:'Native',origin:'collection',sourceKey:key,device:x.request.device,version:x.issue.version,build:x.issue.build,begin:x.request.begin,end:x.request.end,files,format:'auto',policy:'strict'}).asset;selectAssetRun(a,a.runs[0]);toast('已创建独立解析批次，未再次采集设备');}catch(e){toast(e.message);}}
function openReparse(id){let a=findAsset(id),latest=a.runs.at(-1);openModal('重新解析 · '+esc(a.id),`<form onsubmit="submitReparse(event,'${a.id}')"><p>沿用 ${a.files.length} 个已保存原文件，新建批次；已有批次、任务和证据引用不会改写。</p>${parseOptions('reparse',latest.format,latest.policy)}<p id="reparse-error" class="error" role="alert"></p><div class="toolbar"><button class="primary">创建新解析批次</button><button type="button" onclick="closeModal()">取消</button></div></form>`);}
function submitReparse(e,id){e.preventDefault();try{let backup=JSON.stringify(state),a=findAsset(id),r=L.reparse(a,{format:$('#reparse-format').value,policy:$('#reparse-policy').value});if(!save()){state=JSON.parse(backup);throw Error('浏览器存储不足，未保存新批次，历史记录保留。');}closeModal();selectAssetRun(a,r);}catch(err){$('#reparse-error').textContent=err.message;}}
function advanceParse(id,run){let a=findAsset(id),r=a?.runs.find(r=>r.id===run);if(!r)return;persistParseAdvance(a,r);render();}
function persistParseAdvance(a,r){let backup=JSON.stringify(state);L.advance(a,r);syncImportedIssueState();if(save())return true;state=JSON.parse(backup);toast('浏览器存储不足，本次解析步骤未保存；原文件与历史批次保留。请使用更小文件。');return false;}
function runParse(id,run){let key=id+'/'+run;if(parseTimers.has(key))return;let a=findAsset(id),r=a.runs.find(r=>r.id===run);let timer=setInterval(()=>{let persisted=persistParseAdvance(a,r);if(!persisted||!['待解析','解析中'].includes(r.status)){clearInterval(timer);parseTimers.delete(key);}if(page==='logcenter'&&workUI.logKey===key)render();},550);parseTimers.set(key,timer);render();}
function assetParseView(x){let a=x.asset,r=x.run,running=parseTimers.has(x.key),pending=['待解析','解析中'].includes(r.status);return `<div class="panel"><div class="row"><h3>${a.id} · ${a.platform} · ${r.id}</h3>${badge(r.status,r.task?'ok':'warn')}</div><p>来源：${a.origin==='sample'?'Web 合成样例':a.origin==='collection'?'历史回捞的合成文件快照':'本地文件导入'} · 工单 ${esc(a.issueId)} · ${esc(a.device)} · ${esc(a.version)} / ${esc(a.build)}</p><p>声明范围（北京时间）：${esc(a.begin.replace('T',' '))} — ${esc(a.end.replace('T',' '))}</p>${r.records.length?`<p>事件覆盖：${esc(r.records[0].time)} — ${esc(r.records.at(-1).time)}</p>`:''}<div class="notice">本地文件解析与索引演示，无设备推送、服务端上传或真实源码映射。</div><div class="steps">${['文件接收','输入检查','事件解析','索引发布'].map((v,n)=>`<div class="step ${n===2&&r.status==='解析失败'?'fail':r.phase>=n?'done':''}">${v} · ${n===2&&r.status==='解析失败'?'失败':n===3?(r.task?'可查':'未发布'):r.phase>=n?'完成':'待处理'}</div>`).join('')}</div><p>格式：${esc(r.format)} · ${r.policy==='strict'?'严格失败策略':'隔离错误行策略'} · ${r.validCount??r.records.length} 条已识别事件 · ${r.errors.length} 条错误</p><div class="toolbar">${pending?btn(r.phase?'推进下一步':'开始解析',`advanceParse('${a.id}','${r.id}')`,'',running)+btn(running?'正在解析…':'运行解析（演示）',`runParse('${a.id}','${r.id}')`,'primary',running):btn('重新解析原文件',`openReparse('${a.id}')`,'primary')}${btn('阅读解析结果',`openSourceLogs('${x.key}')`,'',!r.task)}${btn('下载解析正文',`downloadSourceSample('${x.key}')`,'',!r.task)}${btn('导出解析记录',`exportAssetRun('${a.id}','${r.id}')`)}</div></div><div class="panel"><h3>原文件与解析结果</h3>${a.files.map((f,n)=>`<div class="row"><div><b>${esc(f.name)}</b><small> · ${f.bytes} B · 原文保留</small><p>${esc(r.status==='解析失败'?'批次解析失败，未发布索引':r.fileResults.find(x=>x.name===f.name)?.status||'等待解析')}</p></div>${btn('下载原文件',`downloadAssetFile('${a.id}',${n})`)}</div>`).join('')}</div><div class="panel"><h3>错误与处理记录</h3>${(r.warnings||[]).map(w=>`<p class="notice">${esc(w)}</p>`).join('')}${r.errors.length?r.errors.slice(0,100).map(e=>`<p class="error">${esc(e.file)} · 第 ${e.line} 条记录：${esc(e.message)}</p>`).join(''):'<p>尚无错误记录。</p>'}${r.events.map(e=>`<p><small>${esc(e.time)}</small><br>${esc(e.text)}</p>`).join('')}</div><div class="panel"><h3>解析批次历史</h3><p>相同原文件的各次配置、结果和任务独立保留。</p>${a.runs.map(h=>`<div class="row"><span>${h.id} · ${esc(h.status)} · ${h.task||'未生成任务'} · ${esc(h.format)} / ${esc(h.policy)}</span>${btn(h.id===r.id?'当前批次':'查看此批次',`selectAssetRun(findAsset('${a.id}'),findAsset('${a.id}').runs.find(r=>r.id==='${h.id}'))`,'',h.id===r.id)}</div>`).join('')}${a.sourceKey?btn('查看原回捞解析记录',`openParsing('${a.sourceKey}')`):''}</div>`;}
function downloadAssetFile(id,n){let a=findAsset(id),f=a.files[n];file(f.name,f.text);}
function exportAssetRun(id,run){let a=findAsset(id),r=a.runs.find(r=>r.id===run);file(a.id+'-'+run+'-parse-record.json',JSON.stringify({asset:{id:a.id,platform:a.platform,device:a.device,version:a.version,build:a.build,files:a.files.map(f=>({name:f.name,bytes:f.bytes}))},run:r},null,2));}
function openIssueLogFiles(){let x=L.sources(state).filter(x=>x.issue.id===state.active).at(-1);if(x){workUI.logStatus='';workUI.logQuery='';workUI.logKey=x.key;workUI.logMode='parse';go('logcenter');}else openIssueLogs();}
const beforeImportedIssue=views.issues;
views.issues=function(){let html=beforeImportedIssue();if(!issueDetail||!issue().logAssets?.length)return html;let importedPanel=`<div class="panel"><h3>导入日志与解析批次</h3>${issue().logAssets.map(a=>`<div class="row"><span>${a.id} · ${esc(a.platform)} · ${a.files.length} 个文件 · ${a.runs.length} 个批次 · ${esc(a.runs.at(-1).status)}</span>${btn('查看导入与解析',`selectAssetRun(findAsset('${a.id}'),findAsset('${a.id}').runs.at(-1))`)}</div>`).join('')}</div>`;return html.replace('<div class="panel"><h3>处理记录</h3>',importedPanel+'<div class="panel"><h3>处理记录</h3>');};
function syncImportedIssueState(){for(let i of state.issues){if(['待采集','待解析'].includes(i.status)&&i.logAssets?.length)i.status=i.logAssets.some(a=>a.runs.some(r=>r.task))?'调查中':'待解析';}}
syncImportedIssueState();
render();
